import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Hermes Stack — Self-hosted AI Brain","description":"Hermes Agent + 9Router + OmniRouter packed into one free Hugging Face Space — a self-hosted AI brain deployable in minutes.","frontmatter":{"title":"Hermes Stack — Self-hosted AI Brain","description":"Hermes Agent + 9Router + OmniRouter packed into one free Hugging Face Space — a self-hosted AI brain deployable in minutes."},"headers":[],"relativePath":"en/projects/hermes-stack/index.md","filePath":"en/projects/hermes-stack/index.md"}`),a={name:`en/projects/hermes-stack/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hermes-stack-—-self-hosted-ai-brain" tabindex="-1">Hermes Stack — Self-hosted AI Brain <a class="header-anchor" href="#hermes-stack-—-self-hosted-ai-brain" aria-label="Permalink to “Hermes Stack — Self-hosted AI Brain”">​</a></h1><p><strong><a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">Hermes Stack</a></strong> is the project that ties my whole AI infrastructure together. It packages <strong>Hermes Agent</strong>, <strong>9Router</strong> and <strong>OmniRouter</strong> into a single Hugging Face Space that deploys in minutes and costs nothing. One click, and you own a cloud-hosted AI brain: an agent runtime, a model router and a console to drive both.</p><h2 id="what-is-inside" tabindex="-1">What is inside <a class="header-anchor" href="#what-is-inside" aria-label="Permalink to “What is inside”">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td>Hermes Agent</td><td>The brain — plans tasks, calls tools, runs automations, remembers context.</td></tr><tr><td>9Router</td><td>Multi-provider model routing for nine upstream families.</td></tr><tr><td>OmniRouter</td><td>My Go router adding weights, quotas and failover on top.</td></tr><tr><td>HF Space</td><td>Free hosting with zero cold-start pain for this class of workload.</td></tr></tbody></table><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to “Why it matters”">​</a></h2><p>Most &quot;AI assistant&quot; setups are either a hosted SaaS you don&#39;t control or a local rig you can&#39;t reach from your phone. Hermes Stack is the third option: <strong>self-hosted, cloud-reachable, and free</strong>. I use it as the coordinator for my other agents — it holds API routes, serves as a webhook brain for automations, and gives every tool in my chain a stable, roammable endpoint.</p><ol><li>Fork the Space (or deploy from the repo with one command).</li><li>Paste your upstream keys — or point it at free bridges like <a href="/Usf/en/projects/glm-free-api/">GLM Free API</a>.</li><li>Talk to it from Telegram, curl, or any OpenAI-compatible client.</li></ol><p>The <a href="/Usf/en/agentic/hermes/">Agentic Coding</a> section covers how Hermes drives the rest of my toolchain day to day. This portfolio itself was coordinated through it — briefs, reviews and deploys all routed through a stack that costs less than a coffee. Which is to say: exactly nothing.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};